import{_ as t,c as a,o,ae as r}from"./chunks/framework.Cd-3tpCq.js";const m=JSON.parse('{"title":"Import Detail (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"gql","title":"Import Detail","query":"query ImportDetail($id: ID!) {\\n  adminSettingsDataTransferImport(id: $id) {\\n    id\\n    _id\\n    code\\n    action\\n    state\\n    processInQueue\\n    validationStrategy\\n    allowedErrors\\n    processedRowsCount\\n    invalidRowsCount\\n    errorsCount\\n    errors\\n    fieldSeparator\\n    filePath\\n    imagesDirectoryPath\\n    errorFilePath\\n    summary\\n    startedAt\\n    completedAt\\n    createdAt\\n    updatedAt\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/admin/settings/data-transfer/imports/13\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminSettingsDataTransferImport\\": {\\n      \\"id\\": \\"/api/admin/settings/data-transfer/imports/13\\",\\n      \\"_id\\": 13,\\n      \\"code\\": \\"products\\",\\n      \\"action\\": \\"append\\",\\n      \\"state\\": \\"validated\\",\\n      \\"processInQueue\\": false,\\n      \\"validationStrategy\\": \\"stop-on-errors\\",\\n      \\"allowedErrors\\": 10,\\n      \\"processedRowsCount\\": 0,\\n      \\"invalidRowsCount\\": 0,\\n      \\"errorsCount\\": 2,\\n      \\"errors\\": [\\n        \\"Required columns not found: sku.\\",\\n        \\"Invalid column names: \\\\\\"Name\\\\\\", \\\\\\"SKU\\\\\\", \\\\\\"Attribute Family\\\\\\", \\\\\\"Price\\\\\\", \\\\\\"Quantity\\\\\\", \\\\\\"ID\\\\\\", \\\\\\"Status\\\\\\", \\\\\\"Category\\\\\\", \\\\\\"Type\\\\\\".\\"\\n      ],\\n      \\"fieldSeparator\\": \\",\\",\\n      \\"filePath\\": \\"imports/695deb404dcb9_abfe03fa9c1740306b93d365d3213c217cdb1f08003dd58a400edd76729f985c.csv\\",\\n      \\"imagesDirectoryPath\\": \\"\\",\\n      \\"errorFilePath\\": null,\\n      \\"summary\\": null,\\n      \\"startedAt\\": null,\\n      \\"completedAt\\": null,\\n      \\"createdAt\\": \\"2026-01-07T16:11:21+05:30\\",\\n      \\"updatedAt\\": \\"2026-01-07T16:12:33+05:30\\"\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/settings/data-transfer-imports/detail.md","filePath":"api/graphql-api/admin/settings/data-transfer-imports/detail.md"}'),d={name:"api/graphql-api/admin/settings/data-transfer-imports/detail.md"};function i(n,e,s,l,c,p){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="import-detail-graphql" tabindex="-1">Import Detail (GraphQL) <a class="header-anchor" href="#import-detail-graphql" aria-label="Permalink to &quot;Import Detail (GraphQL)&quot;">​</a></h1><p>Returns a single import job with the full set of fields — including the heavy <code>errors[]</code> list and <code>summary</code> object that the listing leaves null.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>adminSettingsDataTransferImport(id:)</code></td><td>Query</td><td>Fetch one import with every field</td></tr></tbody></table><h2 id="field-meanings" tabindex="-1">Field meanings <a class="header-anchor" href="#field-meanings" aria-label="Permalink to &quot;Field meanings&quot;">​</a></h2><ul><li><code>code</code> — the entity being imported (<code>products</code>, <code>customers</code>, <code>tax_rates</code>, …).</li><li><code>action</code> — <code>append</code> (insert/update rows) or <code>delete</code> (remove rows).</li><li><code>state</code> — where the job sits in its lifecycle (<code>pending</code>, <code>validated</code>, <code>processing</code>, <code>processed</code>, <code>linked</code>, <code>indexed</code>, <code>completed</code>, <code>cancelled</code>, …).</li><li><code>validationStrategy</code> — <code>stop-on-errors</code> or <code>skip-errors</code>; <code>allowedErrors</code> is the error budget for <code>skip-errors</code>.</li><li><code>processedRowsCount</code> / <code>invalidRowsCount</code> / <code>errorsCount</code> — progress and validation counters.</li><li><code>errors</code> — the list of validation messages (null until validation has run).</li><li><code>summary</code> — created/updated/deleted counts after a run (null until the run completes).</li><li><code>filePath</code> / <code>errorFilePath</code> / <code>imagesDirectoryPath</code> — storage paths; the source file and error report are downloadable over REST only.</li><li><code>startedAt</code> / <code>completedAt</code> / <code>createdAt</code> / <code>updatedAt</code> — lifecycle timestamps.</li></ul><h2 id="quirks" tabindex="-1">Quirks <a class="header-anchor" href="#quirks" aria-label="Permalink to &quot;Quirks&quot;">​</a></h2><ul><li><code>errors</code> and <code>summary</code> are returned as raw JSON values — query them bare (no sub-selection).</li><li><code>errorFilePath</code> and <code>summary</code> stay null until a run has actually produced output.</li></ul><div class="tip custom-block"><p class="custom-block-title">Prerequisites</p><p>The example uses an illustrative <code>id</code>. Replace it with the id of an import that exists in your store — use the <a href="./list.html"><code>adminSettingsDataTransferImports</code></a> query to discover valid ids.</p></div><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',10)]))}const h=t(d,[["render",i]]);export{m as __pageData,h as default};
